    },
    {
      "name": "连续性",
      "category": "相关概念",
      "related_concepts": ["极限", "导数", "函数图像"],
      "definition_snippet": "函数在某点极限值等于函数值时所具有的光滑衔接性质。"
    },
    {
      "name": "函数图像",
